#!/usr/bin/env python3
"""Generate moving moist-energy Metal arithmetic from authoritative GLSL."""
import argparse
from generate_tke_msl import ROOT, translate


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = ROOT / "metal/include/compute/metal/shaders/terrain/moving_energy_msl.hpp"
    source = translate("moving_energy", "terrain").replace(
        "Generated by scripts/dev/shaders/generate_tke_msl.py",
        "Generated by scripts/dev/shaders/generate_moving_energy_msl.py",
    )
    if args.check:
        if not path.exists() or path.read_text() != source:
            raise SystemExit("moving-energy Metal source is stale")
    else:
        path.write_text(source)


if __name__ == "__main__":
    main()
